import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.VWKgVqrc.js";const u=JSON.parse('{"title":"2026-11-03 Agent 核心研究与竞品动态","description":"执行准入、取消与恢复、日志安全、跨设备交付；16 组新增，严格区分合入与发行。","frontmatter":{"title":"2026-11-03 Agent 核心研究与竞品动态","description":"执行准入、取消与恢复、日志安全、跨设备交付；16 组新增，严格区分合入与发行。"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-03.md","filePath":"zh/runtime/daily-intelligence/2026-11-03.md","lastUpdated":null}'),n={name:"zh/runtime/daily-intelligence/2026-11-03.md"};function s(l,e,i,p,c,g){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-11-03-agent-核心研究与竞品动态" tabindex="-1">2026-11-03 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-03-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-03 Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮最重要的变化是：<strong>治理正落到执行准入、调用权限快照、取消清理、持久化证据和恢复所有权的具体契约。</strong> Codex、ADK、LangGraph、OpenHands 与 Paperclip 的变更互相印证；Orca 和 Agentlas 有正式发行，AG2 事件树仍在评审。合入不等于正式发行或生产验收。</p><p>实际执行起点为 <strong>2026-11-03 10:03:00 Asia/Shanghai（02:03:00 UTC）</strong>。常规新增窗口从上次起点 2026-11-02 02:46:49 UTC 开始；commit 使用各来源保留的成功基线。Registry 读取最新 main，仍为 <strong>47 人</strong>。仓库是证据入口，不把贡献者变更写成人物的新论文；赵越始终按“赵越”记录。</p><h2 id="_1-codex-主机执行准入与-mcp-权限快照" tabindex="-1">1. Codex：主机执行准入与 MCP 权限快照 <a class="header-anchor" href="#_1-codex-主机执行准入与-mcp-权限快照" aria-label="Permalink to &quot;1. Codex：主机执行准入与 MCP 权限快照&quot;">​</a></h2><p><strong>状态：#58963 #59020 #59028 MERGED; stable release inclusion NOT VERIFIED</strong></p><p>新增 Host ownership 与执行准入提供者，root turn 也须先取得容量，执行 guard 保留至任务结束；等待期间仍可输入或取消，失败进入 turn 生命周期。预备 MCP 调用同时保留权限及解释它们所需的工作目录、home、临时目录与 workspace roots；Guardian 使用这份上下文审查 denied paths，避免运行时刷新造成审查与准备调用的权限依据不一致。sandbox context 不进入序列化审批 action。</p><p>价值在于区分执行容量、任务所有权与调用权限依据。CodeFlowMu/FCoP 待验证：准入租约是否覆盖实际执行全程，审批是否绑定准备调用时的同一权限上下文。</p><p>值得技术讨论：准入等待中取消或权限刷新时，怎样证明 guard 与审批上下文没有跨 turn 复用？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/openai/codex/pull/58963" target="_blank" rel="noreferrer">#58963</a> · <a href="https://github.com/openai/codex/pull/59020" target="_blank" rel="noreferrer">#59020</a> · <a href="https://github.com/openai/codex/pull/59028" target="_blank" rel="noreferrer">#59028</a></p><h2 id="_2-claude-code-2-1-317-失败阻断、持久化失败与会话隔离" tabindex="-1">2. Claude Code 2.1.317：失败阻断、持久化失败与会话隔离 <a class="header-anchor" href="#_2-claude-code-2-1-317-失败阻断、持久化失败与会话隔离" aria-label="Permalink to &quot;2. Claude Code 2.1.317：失败阻断、持久化失败与会话隔离&quot;">​</a></h2><p><strong>状态：v2.1.317 RELEASED (stable)</strong></p><p>Agent SDK hook 新增 onFailure: block，可在 callback 失败时阻断动作；定时任务意外获得连接器时给出提醒。修复 cloud/self-hosted runner 内嵌 claude -p 复用外层 ID、污染 transcript 或重启恢复到错误会话；自托管可用兼容开关恢复旧 ID 行为。磁盘满或配额导致 transcript/config 写入丢失时，text/json 模式返回 exit 1；完整 NFS export 仍可能漏检。还修复等待计划审批时 runner 重启丢失对话。</p><p>成功退出不能代替持久化成功。CodeFlowMu/FCoP 待验证：hook 故障默认行为、嵌套 session 身份与落盘失败的终态语义。</p><p>值得讨论：NFS 漏检边界及兼容开关启用后 transcript 的隔离保障。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.317" target="_blank" rel="noreferrer">v2.1.317</a></p><h2 id="_3-google-adk-取消真正终止执行-sqlite-写入与-skill-yaml-边界收紧" tabindex="-1">3. Google ADK：取消真正终止执行，SQLite 写入与 Skill/YAML 边界收紧 <a class="header-anchor" href="#_3-google-adk-取消真正终止执行-sqlite-写入与-skill-yaml-边界收紧" aria-label="Permalink to &quot;3. Google ADK：取消真正终止执行，SQLite 写入与 Skill/YAML 边界收紧&quot;">​</a></h2><p><strong>状态：7 commits on default branch; #7652 MERGED via commit; stable release inclusion NOT VERIFIED</strong></p><p>A2A cancel 现在向活跃 Runner 传递 abort，等待清理，并将 INVOCATION_ABORTED 归为 CANCELED；共享 teardown 封闭悬空的普通 tool calls，暂停中的长期调用仍不封闭。两个 SQLite session service 用 BEGIN IMMEDIATE 把 stale check、状态合并与写入置于同一写锁，防止并发覆盖。Skill 执行去掉自由 command，统一验证路径与结构化参数；YAML 加载阻止私有开关及可执行入口，并补齐旧 from_config 的 denylist。评测器遇到 rubric 缺 verdict 返回未评分，invocation-level rubric 对齐限制仍在。</p><p>这些分别修复“状态已取消但工具仍跑”、并发状态丢失、配置升级为执行权限及缺失证据被计分。CodeFlowMu/FCoP 关联均待本地验证。</p><p>值得讨论：cancel 返回前副作用停止的证明、长期调用例外及跨 invocation rubric 对齐。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/google/adk-python/commit/bc0b41871699a70a3bf1169bb7e7ff91d2db5e31" target="_blank" rel="noreferrer">bc0b418716</a> · <a href="https://github.com/google/adk-python/commit/c3abc93d11260e87bb1bd1445faa25a6b5b0d681" target="_blank" rel="noreferrer">c3abc93d11</a> · <a href="https://github.com/google/adk-python/commit/ff61524bb1378bd355d92b5b88955ea142f83be0" target="_blank" rel="noreferrer">ff61524bb1</a> · <a href="https://github.com/google/adk-python/commit/d1f2add4fe759c7c9109cba5eae2b20809fc6795" target="_blank" rel="noreferrer">d1f2add4fe</a> · <a href="https://github.com/google/adk-python/commit/1c7e8f76b6c995b69b5cc9ec1ac2960988388a1d" target="_blank" rel="noreferrer">1c7e8f76b6</a> · <a href="https://github.com/google/adk-python/commit/14765ab2bf78500e167ccd08c97cffd9b143a80d" target="_blank" rel="noreferrer">14765ab2bf</a> · <a href="https://github.com/google/adk-python/commit/abd8f0f69bab8d5ee9b3e0e5a88d42b57e69b3d6" target="_blank" rel="noreferrer">abd8f0f69b</a></p><h2 id="_4-langgraph-python-sdk-正常断流不再直接等同完成" tabindex="-1">4. LangGraph Python SDK：正常断流不再直接等同完成 <a class="header-anchor" href="#_4-langgraph-python-sdk-正常断流不再直接等同完成" aria-label="Permalink to &quot;4. LangGraph Python SDK：正常断流不再直接等同完成&quot;">​</a></h2><p><strong>状态：#9554 MERGED; release inclusion NOT VERIFIED</strong></p><p>run stream 正常关闭且没有 end/error 时，若 Location 指向带 thread 的 run stream，SDK 查询 run 状态；pending/running 或暂时错误触发原重连预算、退避与 cursor 机制。终态或非 429 的 4xx 等沿用结束行为。thread stream、无 Location 和旧式 threadless Location 不变。代价是通常多一次 GET，可能重新下载含大 input 的 run record。</p><p>防止代理超时/服务器重启产生截断答案却被当成功。CodeFlowMu/FCoP 待验证：连接终止与任务终态是否独立表达，并保留重连成本。</p><p>值得讨论：轻量终态查询能否避免重取 input，同时保留 cursor 幂等性？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/langchain-ai/langgraph/pull/9554" target="_blank" rel="noreferrer">#9554</a></p><h2 id="_5-openhands-sdk-bash-事件日志增加静态加密" tabindex="-1">5. OpenHands SDK：bash 事件日志增加静态加密 <a class="header-anchor" href="#_5-openhands-sdk-bash-事件日志增加静态加密" aria-label="Permalink to &quot;5. OpenHands SDK：bash 事件日志增加静态加密&quot;">​</a></h2><p><strong>状态：#6343 MERGED; general stable rollout NOT VERIFIED</strong></p><p>公开 PR 描述的安全披露涉及 bash 日志随 sandbox 文件树暴露，命令和输出可能含凭证。BashEventService 配置 cipher 后写 Fernet token，并支持旧密钥回读；无法解密的文件记录错误后跳过。旧明文仍可读且不自动重加密；没有 secret key 时仍写明文。部署侧移出公开树、改用 upload 交付 secrets 的修复属于其他仓库，不能据此声称所有部署已安全。PR 未执行真实 sandbox 验证。</p><p>安全边界覆盖日志、卷与恢复归档。CodeFlowMu/FCoP 待验证：有无密钥、轮换与旧备份各自的真实保护范围。</p><p>值得讨论：旧明文迁移或安全删除策略，以及无法解密时是否会把审计缺口显式呈现。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/OpenHands/software-agent-sdk/pull/6343" target="_blank" rel="noreferrer">#6343</a></p><h2 id="_6-langfuse-请求捕获内存有界-mcp-工具失败显式返回" tabindex="-1">6. Langfuse：请求捕获内存有界，MCP 工具失败显式返回 <a class="header-anchor" href="#_6-langfuse-请求捕获内存有界-mcp-工具失败显式返回" aria-label="Permalink to &quot;6. Langfuse：请求捕获内存有界，MCP 工具失败显式返回&quot;">​</a></h2><p><strong>状态：#19576 #19579 MERGED; release inclusion NOT VERIFIED</strong></p><p>Gateway 保留 raw JSON，避免 5 MiB 请求展开为 128–483 MiB 的 Value 树；上游独立计数分配器测得新路径约 5 MiB，非本地实测。需要解析的配置/metadata 共用 64 KiB 预算，超限字段留在 input；原始 JSON 格式保留。上游响应解析不在此次范围。MCP handler 失败改为 isError: true 工具结果，使获批调用的失败进入 Agent 对话，而不是只抛协议错误。</p><p>审计链本身不能绕过资源准入，也不能丢失工具失败。CodeFlowMu/FCoP 待验证：捕获开销预算和失败事件在恢复/评测中的可见性。</p><p>值得讨论：原始 JSON 保留与字段解析预算怎样同时满足检索和隐私需求。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/langfuse/langfuse/pull/19576" target="_blank" rel="noreferrer">#19576</a> · <a href="https://github.com/langfuse/langfuse/pull/19579" target="_blank" rel="noreferrer">#19579</a></p><h2 id="_7-github-mcp-server-issue-artifact-工具实验性合入" tabindex="-1">7. GitHub MCP Server：Issue Artifact 工具实验性合入 <a class="header-anchor" href="#_7-github-mcp-server-issue-artifact-工具实验性合入" aria-label="Permalink to &quot;7. GitHub MCP Server：Issue Artifact 工具实验性合入&quot;">​</a></h2><p><strong>状态：#3554 MERGED; experimental opt-in; release inclusion NOT VERIFIED</strong></p><p>新增 issue_artifact_read/list-get 与 issue_artifact_write/create-update-delete，用 Issue 保存计划、指令和参考资料。issue_artifacts 显式开启，Insiders 也默认关闭；read-only 仅暴露读工具。使用 issue-scoped artifact_number；开关不授予 API 权限。lockdown 因返回记录无作者身份可供信任检查而拒绝全部操作；写失败不自动重试。作者验证了单个仓库/凭证的生命周期，不能推广为全主机兼容。</p><p>为任务证据提供结构化载体，同时暴露作者身份缺失的信任边界。CodeFlowMu/FCoP 待验证：证据对象的身份、授权及重试策略。</p><p>值得讨论：缺少作者元数据时，能否提供可审计的受限读取方式？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/github/github-mcp-server/pull/3554" target="_blank" rel="noreferrer">#3554</a></p><h2 id="_8-paperclip-丢失-acquire-回复、重启后的-stop-与-workspace-写者等待" tabindex="-1">8. Paperclip：丢失 acquire 回复、重启后的 Stop 与 workspace 写者等待 <a class="header-anchor" href="#_8-paperclip-丢失-acquire-回复、重启后的-stop-与-workspace-写者等待" aria-label="Permalink to &quot;8. Paperclip：丢失 acquire 回复、重启后的 Stop 与 workspace 写者等待&quot;">​</a></h2><p><strong>状态：#18692 #18682 #18691 MERGED; stable release inclusion NOT VERIFIED</strong></p><p>支持 opted-in provider 从创建 journal 恢复 acquire 回复丢失的 resource identity，但 identity 不能当 termination proof；仍须精确停止回执才能释放所有权。重启后仅凭准确绑定的 pending Stop、audit、恢复 lease/generation 与原预算 reservation，重连旧 session 完成清理，不开启新付费 turn；缺 usage 保留债务。父任务仍写入继承 workspace 时，子任务走可继续的 scheduled retry，stale 或已停但未保存的 writer 仍需 reconciliation。PR 留有受控 PostgreSQL/IPC 与 CI 证据，不能当生产 VM/托管凭证已验收。</p><p>学习价值高；竞争风险高；雷达：恢复和执行所有权实现继续增强，生产恢复成熟度尚不能据此上调至已验证。CodeFlowMu/FCoP 待验证：identity、termination receipt、取消 ACK 与计费结算分别举证。</p><p>值得讨论：原机器绑定/凭证丢失时怎样保留不确定性，并避免 cleanup 意外提交新 turn？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/paperclipai/paperclip/pull/18692" target="_blank" rel="noreferrer">#18692</a> · <a href="https://github.com/paperclipai/paperclip/pull/18682" target="_blank" rel="noreferrer">#18682</a> · <a href="https://github.com/paperclipai/paperclip/pull/18691" target="_blank" rel="noreferrer">#18691</a></p><h2 id="_9-beads-配置执行权、argv-注入与本机代理认证修复" tabindex="-1">9. Beads：配置执行权、argv 注入与本机代理认证修复 <a class="header-anchor" href="#_9-beads-配置执行权、argv-注入与本机代理认证修复" aria-label="Permalink to &quot;9. Beads：配置执行权、argv 注入与本机代理认证修复&quot;">​</a></h2><p><strong>状态：#7879 #7881 #7885 MERGED; release inclusion NOT VERIFIED</strong></p><p>仓库 .beads/.env 不再导入 credential runner/editor/pager 等可执行配置，mail.delegate 仅信任进程环境和用户级配置，工作区 API 拒绝写入。拒绝以 - 开头的 sync remote，MCP argv 用 -- 与 --flag=value 防止文本变为参数。loopback 数据连接要求 owner-only secret 派生 HMAC token；控制探测改 nonce/HMAC，不直接发 secret；Dolt 使用验证后的私有配置快照。共享主机 CA 检查补齐 primary group。新旧代理不兼容，升级需停止旧代理。</p><p>学习价值高；竞争风险中高；雷达：安全机制改善，同时记录真实升级兼容成本。CodeFlowMu/FCoP 待验证：仓库数据与用户执行权、本机多用户边界及配置检查到使用间的一致性。</p><p>值得讨论：Windows 等无同类 listener-owner 检查的平台，ready-line 与私有快照的剩余边界。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/gastownhall/beads/pull/7879" target="_blank" rel="noreferrer">#7879</a> · <a href="https://github.com/gastownhall/beads/pull/7881" target="_blank" rel="noreferrer">#7881</a> · <a href="https://github.com/gastownhall/beads/pull/7885" target="_blank" rel="noreferrer">#7885</a></p><h2 id="_10-orca-1-4-246-orchestrator-v3-与手机操作正式发行" tabindex="-1">10. Orca 1.4.246：Orchestrator V3 与手机操作正式发行 <a class="header-anchor" href="#_10-orca-1-4-246-orchestrator-v3-与手机操作正式发行" aria-label="Permalink to &quot;10. Orca 1.4.246：Orchestrator V3 与手机操作正式发行&quot;">​</a></h2><p><strong>状态：v1.4.246 RELEASED (stable)</strong></p><p>发行说明宣布 Orchestrator V3 同时面向 CLI Agent 与 Chat UI，并过滤编排 worker 通知。Chat UI 移出 experimental，支持排队 follow-up、运行中插入、达到用量上限后换账号或 harness 继续。手机可运行 automations、处理合并冲突与 PR 操作；浏览器/计算机使用和终端恢复也列入更新。“更省 token、更可靠”只有发行说明主张，本轮无独立 benchmark。</p><p>学习价值高；竞争风险高；雷达：正式交付与手机操作面增强，性能优势暂不量化。CodeFlowMu/FCoP 待验证：手机应控制任务和证据，跨账号/harness 续跑需校验身份与权限。</p><p>值得讨论：换账号续跑时如何重新确认已有工具权限、凭证边界和副作用归属？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/stablyai/orca/releases/tag/v1.4.246" target="_blank" rel="noreferrer">v1.4.246</a></p><h2 id="_11-agentlas-os-独立-engine-稳定通道与宿主环境隔离" tabindex="-1">11. Agentlas OS：独立 engine 稳定通道与宿主环境隔离 <a class="header-anchor" href="#_11-agentlas-os-独立-engine-稳定通道与宿主环境隔离" aria-label="Permalink to &quot;11. Agentlas OS：独立 engine 稳定通道与宿主环境隔离&quot;">​</a></h2><p><strong>状态：os-v1.2.73 / os-v1.2.74 RELEASED (stable standalone channel); legacy latest unchanged</strong></p><p>独立 engine 安装到 ~/.agentlas/os-runtime，经 os-bin launcher 启动，不改已有 Desktop runtime。可选 memory、索引、自动更新和 telemetry 等默认关闭；engine 移除 graph automation 与 Telegram/Connect 命令，数据不删除。1.2.74 阻止 host session 将 engine locator 环境变量传给 Claude/Codex，避免其他旧插件替换独立 runtime；Antigravity 注册仅在显式执行时发生。旧 v1.2.72 安装不自动切通道。</p><p>学习价值中高；竞争风险中；雷达：从单体转独立引擎的交付边界值得持续观察，不等于验证了可靠性。CodeFlowMu/FCoP 待验证：安装通道、宿主插件与引擎定位环境变量隔离。</p><p>值得讨论：同机多版本 host/plugin/engine 的解析优先级和诊断证据。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.73" target="_blank" rel="noreferrer">os-v1.2.73</a> · <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.74" target="_blank" rel="noreferrer">os-v1.2.74</a></p><h2 id="_12-orkas-无效转录与写入失败保留原始证据" tabindex="-1">12. Orkas：无效转录与写入失败保留原始证据 <a class="header-anchor" href="#_12-orkas-无效转录与写入失败保留原始证据" aria-label="Permalink to &quot;12. Orkas：无效转录与写入失败保留原始证据&quot;">​</a></h2><p><strong>状态：#161 MERGED; release inclusion NOT VERIFIED</strong></p><p>替换可用 transcript 前验证原生 Whisper 输出，并通过已有 atomic JSON writer 发布有效结果；无效输出返回可恢复工具错误，中断写入保留旧 transcript 与源媒体。保留有效静音、显式 retry 与 workspace confinement。上游报告 231 个确定性用例和三个 Electron 旅程通过，但原生 ASR 用受控 executable，未验证真实转录质量和物理 Windows 执行。</p><p>学习价值中高；竞争风险中；雷达：证据保留与失败恢复改善，Windows 交付和真实质量仍待验证。CodeFlowMu/FCoP 待验证：失败重试不得覆盖最后一份可用成果。</p><p>值得讨论：atomic publish 失败时，如何区分可重试输出和不可再生成的源证据？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/Orkas-AI/Orkas/pull/161" target="_blank" rel="noreferrer">#161</a></p><h2 id="_13-eigent-事件时间线改为默认-回滚需要重新构建" tabindex="-1">13. Eigent：事件时间线改为默认，回滚需要重新构建 <a class="header-anchor" href="#_13-eigent-事件时间线改为默认-回滚需要重新构建" aria-label="Permalink to &quot;13. Eigent：事件时间线改为默认，回滚需要重新构建&quot;">​</a></h2><p><strong>状态：#2114 MERGED after v1.0.7; next release inclusion NOT VERIFIED</strong></p><p>正常构建默认启用事件时间线，包含 inline approvals、任务叙事与模型切换；VITE_CHATBOX_EVENT_BUS=false 回到旧视图，但这是 build-time 开关，需重新构建。没有时间线事件的历史 session 仍回落旧视图。上游默认/回滚测试各覆盖 992 用例，并披露基线失败；PR 未完成 app 内人工核验，旧 renderer 暂保留至少两至三个 release。</p><p>学习价值中高；竞争风险中；雷达：治理事件开始成为默认产品交互，保留交付/人工验收缺口。CodeFlowMu/FCoP 待验证：审批与状态应从事件投影，且历史兼容/回滚须有证据。</p><p>值得讨论：旧 session 缺事件时，哪些治理事实可以可靠重建，哪些必须标为未知？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/eigent-ai/eigent/pull/2114" target="_blank" rel="noreferrer">#2114</a></p><h2 id="_14-paradev-原-superset-附件交付、休眠管理与定时漏触发" tabindex="-1">14. Paradev（原 Superset）：附件交付、休眠管理与定时漏触发 <a class="header-anchor" href="#_14-paradev-原-superset-附件交付、休眠管理与定时漏触发" aria-label="Permalink to &quot;14. Paradev（原 Superset）：附件交付、休眠管理与定时漏触发&quot;">​</a></h2><p><strong>状态：#9064 #9257 #9274 #9270 MERGED; release/deployed behavior NOT VERIFIED</strong></p><p>附件按 local/remote/cloud 位置选择本机复制、远程传输或 fileId 存储；本机大文件可作为 path，relay 有 25 MB 限制，尚欠整合后的 desktop/mobile/重建 box 人工矩阵，部分持久 event log 与共享视图未实现。CLI 管理休眠 cloud workspace 不唤醒 sandbox，restart/unarchive/真实同事共享未做生产实测。RRULE 的 BYHOUR/BYMINUTE/BYSECOND 数值排序修复跨午夜及乱序漏触发；上游只读查到四个触发器受影响，合入后部署行为未核验。chat 修复等待审批、后台 hold 和 compaction steering 状态，但 SUPER-2700 根因仍未确认。</p><p>学习价值高；竞争风险高；雷达：跨设备工作区与调度能力增强，但不把合入或单测当完整生产验收。CodeFlowMu/FCoP 待验证：附件位置/身份、控制面独立于运行面，以及预期触发槽的独立核对。</p><p>值得讨论：调度库从未产出的时间槽如何被独立监测，以及跨设备附件何时可宣称持久交付？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/ParadevAI/Paradev/pull/9064" target="_blank" rel="noreferrer">#9064</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9257" target="_blank" rel="noreferrer">#9257</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9274" target="_blank" rel="noreferrer">#9274</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9270" target="_blank" rel="noreferrer">#9270</a></p><h2 id="_15-ag2-subagent-事件树与作用域变量方案仍在评审" tabindex="-1">15. AG2：subagent 事件树与作用域变量方案仍在评审 <a class="header-anchor" href="#_15-ag2-subagent-事件树与作用域变量方案仍在评审" aria-label="Permalink to &quot;15. AG2：subagent 事件树与作用域变量方案仍在评审&quot;">​</a></h2><p><strong>状态：#3526 #3523 #3524 OPEN (not draft); NOT MERGED / NOT RELEASED</strong></p><p>本轮 #3526 head 在 11 月 2 日 21:20 UTC 更新，补齐 usage/task lifecycle 原类型转发与 provenance、自定义 inert event 不入对话历史。方案让祖先观测后代事件、向具体 invocation 回复并连同后代取消；operational ChildEvent 不触发祖先工具或 HITL，作用域变量限定同一 invocation tree，fresh root 复制调用者输入。PR 报告分层测试通过，仍需要 review approval。这是旧方案的本轮集成修订，不是新发行能力。</p><p>对子 Agent 可观测性、计费归属与跨用户状态隔离有研究价值。CodeFlowMu/FCoP 待验证：观察事件不能获得执行权限，存储/压缩后仍保留原始 spender 与 invocation 身份。</p><p>值得讨论：祖先可见性、定向取消和 shared bindings 的边界能否用同一 invocation provenance 验证？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/ag2ai/ag2/pull/3526" target="_blank" rel="noreferrer">#3526</a> · <a href="https://github.com/ag2ai/ag2/pull/3523" target="_blank" rel="noreferrer">#3523</a> · <a href="https://github.com/ag2ai/ag2/pull/3524" target="_blank" rel="noreferrer">#3524</a></p><h2 id="_16-copilot-cli-预发行修复凭证回显、hook-与后台完成投递" tabindex="-1">16. Copilot CLI：预发行修复凭证回显、hook 与后台完成投递 <a class="header-anchor" href="#_16-copilot-cli-预发行修复凭证回显、hook-与后台完成投递" aria-label="Permalink to &quot;16. Copilot CLI：预发行修复凭证回显、hook 与后台完成投递&quot;">​</a></h2><p><strong>状态：v1.0.106-3 / -4 / -5 RELEASED (prerelease); not stable</strong></p><p>最新预发行避免无效 HTTP header 形式的 BYOK key 被写入错误或 session log；hook 返回空 prompt 不再向模型发空串，并给字段警告；仓库禁用的 MCP enable 显式失败。autopilot 停止后到达的后台完成消息延至下一条用户消息投递。此前两个同轮预发行补齐终端控制字符转义、hook 深度及权限/会话恢复错误。仅按预发行能力记录。</p><p>对凭证隔离、hook 契约和异步结果不丢失有价值。CodeFlowMu/FCoP 关联待验证；不建议仅凭 release notes 推断本地有相同问题。</p><p>值得讨论：延迟投递如何保持原 task/session 身份，避免跨 turn 误归属？</p><p><strong>原始公开来源：</strong> <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-5" target="_blank" rel="noreferrer">v1.0.106-5</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-4" target="_blank" rel="noreferrer">v1.0.106-4</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-3" target="_blank" rel="noreferrer">v1.0.106-3</a></p><h2 id="跨项目共振与分类处置" tabindex="-1">跨项目共振与分类处置 <a class="header-anchor" href="#跨项目共振与分类处置" aria-label="Permalink to &quot;跨项目共振与分类处置&quot;">​</a></h2><ul><li><strong>动作前治理</strong>：Codex 的 Host admission / MCP snapshot、ADK 的 Skill/YAML 约束、Beads 的用户级执行配置，共同强调“看到了配置”不等于“获得执行授权”。</li><li><strong>完成与恢复语义</strong>：ADK 真正取消、LangGraph 查询 run、Paperclip 精确 Stop/receipt、Paradev 等待输入状态，都在分开连接、任务、后台工作和清理终态。</li><li><strong>证据与资源边界</strong>：OpenHands 日志加密、Langfuse 有界捕获、Orkas 原子替换、AG2 provenance，要求既能恢复事实，也能解释缺口与成本。</li><li><strong>交付与手机</strong>：Orca 正式手机操作、Paradev 分位置附件、Agentlas 独立 engine 表明控制面与执行面正在分离；没有据此宣称跨设备安全或生产可靠性已验证。</li></ul><p>本轮为信息收集与分类报告：<strong>16 组信息线索；本地研究实验 0，实验文章 0，正式开发评审 0，对外评论 0</strong>。上游测试和性能数字均为上游证据，不是本地实验。所有 CodeFlowMu/FCoP 关联都是待验证线索，不生成派工，不修改 Research Runtime 生命周期。适合互动的技术问题已逐项记录，未发送评论。</p><h2 id="双源核查、去重与覆盖缺口" tabindex="-1">双源核查、去重与覆盖缺口 <a class="header-anchor" href="#双源核查、去重与覆盖缺口" aria-label="Permalink to &quot;双源核查、去重与覆盖缺口&quot;">​</a></h2><p>GitHub 已检查 88 个目标仓库的 commit 查询、最近 5 条更新 Issue/PR、最近 3 条 Release，保存 500 条 commit（含 Paradev canonical 补查）、174 条 Issue/PR 与 189 条 Release 记录；这些是读取记录数，不是新增或成果数。Orca commit 仅首 100 条、分页未完；TSA 仓库无法访问。Superset 旧路径返回迁移，沿此前已核验的 Paradev canonical 补查 30 个 commit，并保持原雷达身份。Issue/PR 满 5 条、Release 满 3 条均标为部分覆盖，不推进其完整历史基线。曾中断的 30 条列表批次不计成功，随后 88 个目标均按 5 条上限重查。旧的待补查窗口继续保留，不把未知当无变化。</p><p>第二来源类型单独核查 <a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">Cursor changelog</a>、<a href="https://cursor.com/docs/release-notes/cloud-agents" target="_blank" rel="noreferrer">Cloud Agents release notes</a>、<a href="https://auditable-agents.github.io/" target="_blank" rel="noreferrer">Auditable Agents</a>、<a href="https://auditcommons.org/latest/" target="_blank" rel="noreferrer">Audit Commons latest</a> 及赵越定向公开检索。可读页面没有核实到本轮新日期的技术发布；不把 October 25/27 材料或 upcoming talk 冒充今日新增。USC 主页返回 502；另一未核验地址访问失败，不用它确认身份。未穷尽 47 人全部 X 回复/线程，也未完整检查全部 Roadmap/Discussion、README、License 和安全公告，不能宣称全量无更新。两类来源没有混称，GitHub 一手工程证据可独立支撑上述事实。</p><p>赵越指定仓库与六位治理对象的已核查 commit 无新增；MAST、AgentSpec、manifests、隐写与失败归因保持各自关系，bulbasaur-skill-cli 仍仅为相关项目，<strong>不是 AGENTSAFE 官方 Artifact</strong>。Registry 原仓库路径保留，不因名称相似替换作者或实现。</p><p>已对照既有日档去重。MCP #3471/#3452 虽有近期 updated_at，但已读正文、关闭和评论均为旧材料，剔除今日新增；AG2 仅把本轮 head 集成修订作为新变化。历史空档及分页欠账以本地 coverage/checkpoint 为准。</p><h2 id="存档与网站发布说明" tabindex="-1">存档与网站发布说明 <a class="header-anchor" href="#存档与网站发布说明" aria-label="Permalink to &quot;存档与网站发布说明&quot;">​</a></h2><p>本日档及英文镜像、两个日期索引是本次唯一源码写入范围，使用 GitHub app tooling 提交。网站沿用原 VitePress 页面与固定入口、公开快照；提交后须构建、非强制 gh-pages 发布，核对匹配的 Pages run 和线上双语索引唯一首项及全文。最终验收结果以本轮聊天汇报和本地 publication-receipt 为准；源码存在本身不代表上线完成。</p>',109)])])}const d=a(n,[["render",s]]);export{u as __pageData,d as default};
